using Microsoft.Data.Sqlite;
namespace TiendaMascotasHuevos;
public sealed class SqliteStore : IProductoRepository,IClienteRepository,IVentaRepository,IInventarioRepository {
    readonly Database db;
    public SqliteStore(Database db) => this.db=db;
    static Producto MapProducto(SqliteDataReader r) => new(r.GetInt32(0),r.GetString(1),r.GetString(2),(Categoria)r.GetInt32(3),r.GetString(4),r.GetDecimal(5),r.GetInt32(6),r.GetInt32(7),r.GetInt32(8)!=0);
    public IReadOnlyList<Producto> Listar(bool soloActivos=true) { using var c=db.Open(); using var q=c.CreateCommand(); q.CommandText="SELECT id,codigo,nombre,categoria,presentacion,precio,stock,stock_minimo,activo FROM productos WHERE @todos=1 OR activo=1 ORDER BY nombre"; q.Parameters.AddWithValue("@todos",soloActivos?0:1); using var r=q.ExecuteReader(); var a=new List<Producto>(); while(r.Read())a.Add(MapProducto(r)); return a; }
    public int Guardar(Producto p) { Reglas.Producto(p); using var c=db.Open(); using var q=c.CreateCommand(); q.CommandText=p.Id==0 ? "INSERT INTO productos(codigo,nombre,categoria,presentacion,precio,stock,stock_minimo,activo) VALUES(@cod,@nom,@cat,@pres,@pre,@sto,@min,@act); SELECT last_insert_rowid();" : "UPDATE productos SET codigo=@cod,nombre=@nom,categoria=@cat,presentacion=@pres,precio=@pre,stock_minimo=@min,activo=@act WHERE id=@id; SELECT @id;"; q.Parameters.AddWithValue("@id",p.Id); q.Parameters.AddWithValue("@cod",p.Codigo.Trim()); q.Parameters.AddWithValue("@nom",p.Nombre.Trim()); q.Parameters.AddWithValue("@cat",(int)p.Categoria); q.Parameters.AddWithValue("@pres",p.Presentacion); q.Parameters.AddWithValue("@pre",p.Precio); q.Parameters.AddWithValue("@sto",p.Stock); q.Parameters.AddWithValue("@min",p.StockMinimo); q.Parameters.AddWithValue("@act",p.Activo?1:0); return Convert.ToInt32(q.ExecuteScalar()); }
    public IReadOnlyList<Cliente> ListarClientes() { using var c=db.Open(); using var q=c.CreateCommand(); q.CommandText="SELECT id,nombre,documento,telefono,email,direccion FROM clientes ORDER BY nombre"; using var r=q.ExecuteReader(); var a=new List<Cliente>(); while(r.Read())a.Add(new(r.GetInt32(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5))); return a; }
    IReadOnlyList<Cliente> IClienteRepository.Listar() => ListarClientes();
    IReadOnlyList<VentaResumen> IVentaRepository.Listar() => ListarVentas();
    public int Guardar(Cliente x) { Reglas.Cliente(x); using var c=db.Open(); using var q=c.CreateCommand(); q.CommandText=x.Id==0?"INSERT INTO clientes(nombre,documento,telefono,email,direccion) VALUES(@n,@d,@t,@e,@a); SELECT last_insert_rowid();":"UPDATE clientes SET nombre=@n,documento=@d,telefono=@t,email=@e,direccion=@a WHERE id=@id; SELECT @id;"; q.Parameters.AddWithValue("@id",x.Id); q.Parameters.AddWithValue("@n",x.Nombre); q.Parameters.AddWithValue("@d",x.Documento); q.Parameters.AddWithValue("@t",x.Telefono); q.Parameters.AddWithValue("@e",x.Email); q.Parameters.AddWithValue("@a",x.Direccion); return Convert.ToInt32(q.ExecuteScalar()); }
    public int Registrar(NuevaVenta v) {
        Reglas.Venta(v); using var c=db.Open(); using var tx=c.BeginTransaction();
        if(v.ClienteId.HasValue){using var check=c.CreateCommand();check.Transaction=tx;check.CommandText="SELECT COUNT(*) FROM clientes WHERE id=@id";check.Parameters.AddWithValue("@id",v.ClienteId.Value);if(Convert.ToInt32(check.ExecuteScalar())==0)throw new ArgumentException("Cliente inexistente.");}
        var lines=new List<ItemVenta>();
        foreach(var item in v.Items) {
            using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT nombre,precio,stock,activo FROM productos WHERE id=@id";q.Parameters.AddWithValue("@id",item.ProductoId);using var r=q.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Producto inexistente."); var nombre=r.GetString(0);var precio=r.GetDecimal(1);var stock=r.GetInt32(2);var activo=r.GetInt32(3)==1;if(!activo || stock<item.Cantidad)throw new InvalidOperationException($"Sin stock suficiente: {nombre}");lines.Add(new(item.ProductoId,nombre,item.Cantidad,precio));
        }
        decimal total=lines.Sum(x=>x.Subtotal);
        using(var q=c.CreateCommand()){q.Transaction=tx;q.CommandText="INSERT INTO ventas(fecha,cliente_id,medio_pago,total) VALUES(@f,@c,@m,@t);SELECT last_insert_rowid();";q.Parameters.AddWithValue("@f",DateTime.UtcNow.ToString("O"));q.Parameters.AddWithValue("@c",(object?)v.ClienteId??DBNull.Value);q.Parameters.AddWithValue("@m",v.MedioPago);q.Parameters.AddWithValue("@t",total);var id=Convert.ToInt32(q.ExecuteScalar());
            foreach(var line in lines){using var d=c.CreateCommand();d.Transaction=tx;d.CommandText="INSERT INTO venta_items(venta_id,producto_id,nombre,cantidad,precio_unitario) VALUES(@v,@p,@n,@c,@pr);UPDATE productos SET stock=stock-@c WHERE id=@p AND stock>=@c;INSERT INTO movimientos(producto_id,fecha,delta,motivo) VALUES(@p,@f,@delta,@mot);";d.Parameters.AddWithValue("@v",id);d.Parameters.AddWithValue("@p",line.ProductoId);d.Parameters.AddWithValue("@n",line.Nombre);d.Parameters.AddWithValue("@c",line.Cantidad);d.Parameters.AddWithValue("@pr",line.PrecioUnitario);d.Parameters.AddWithValue("@f",DateTime.UtcNow.ToString("O"));d.Parameters.AddWithValue("@delta",-line.Cantidad);d.Parameters.AddWithValue("@mot",$"Venta #{id}");d.ExecuteNonQuery();}
            tx.Commit();return id;}
    }
    public IReadOnlyList<VentaResumen> ListarVentas() { using var c=db.Open();using var q=c.CreateCommand();q.CommandText="SELECT v.id,v.fecha,v.cliente_id,COALESCE(c.nombre,'Consumidor final'),v.medio_pago,v.total FROM ventas v LEFT JOIN clientes c ON c.id=v.cliente_id ORDER BY v.id DESC";using var r=q.ExecuteReader();var a=new List<VentaResumen>();while(r.Read())a.Add(new(r.GetInt32(0),DateTime.Parse(r.GetString(1)).ToLocalTime(),r.IsDBNull(2)?null:r.GetInt32(2),r.GetString(3),r.GetString(4),r.GetDecimal(5)));return a; }
    public IReadOnlyList<ItemVenta> Detalle(int ventaId) {using var c=db.Open();using var q=c.CreateCommand();q.CommandText="SELECT producto_id,nombre,cantidad,precio_unitario FROM venta_items WHERE venta_id=@id";q.Parameters.AddWithValue("@id",ventaId);using var r=q.ExecuteReader();var a=new List<ItemVenta>();while(r.Read())a.Add(new(r.GetInt32(0),r.GetString(1),r.GetInt32(2),r.GetDecimal(3)));return a;}
    public void Ajustar(int productoId,int delta,string motivo){if(delta==0||string.IsNullOrWhiteSpace(motivo))throw new ArgumentException("Indique ajuste y motivo.");using var c=db.Open();using var tx=c.BeginTransaction();using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="UPDATE productos SET stock=stock+@d WHERE id=@id AND stock+@d>=0";q.Parameters.AddWithValue("@d",delta);q.Parameters.AddWithValue("@id",productoId);if(q.ExecuteNonQuery()!=1)throw new InvalidOperationException("Producto inexistente o stock insuficiente.");using var m=c.CreateCommand();m.Transaction=tx;m.CommandText="INSERT INTO movimientos(producto_id,fecha,delta,motivo) VALUES(@id,@f,@d,@m)";m.Parameters.AddWithValue("@id",productoId);m.Parameters.AddWithValue("@f",DateTime.UtcNow.ToString("O"));m.Parameters.AddWithValue("@d",delta);m.Parameters.AddWithValue("@m",motivo);m.ExecuteNonQuery();tx.Commit();}
    public IReadOnlyList<MovimientoStock> Movimientos(int productoId){using var c=db.Open();using var q=c.CreateCommand();q.CommandText="SELECT id,producto_id,fecha,delta,motivo FROM movimientos WHERE producto_id=@id ORDER BY id DESC";q.Parameters.AddWithValue("@id",productoId);using var r=q.ExecuteReader();var a=new List<MovimientoStock>();while(r.Read())a.Add(new(r.GetInt32(0),r.GetInt32(1),DateTime.Parse(r.GetString(2)),r.GetInt32(3),r.GetString(4)));return a;}
}
